package ae.jobs;

import java.util.List;

/** Facts recorded in the journal. State is a pure fold over these events. */
sealed interface Event {
    String id();

    record Submitted(String id, String type, String payload, List<String> dependsOn, long runAt) implements Event {
    }

    record Started(String id, int attempt) implements Event {
    }

    record Succeeded(String id) implements Event {
    }

    /** Attempt failed; the job returns to PENDING and becomes due at {@code nextRunAt}. */
    record Failed(String id, int attempt, String error, long nextRunAt) implements Event {
    }

    record Died(String id, int attempt, String error) implements Event {
    }

    record Cancelled(String id, String reason) implements Event {
    }
}

package ae.jobs;

/**
 * Exponential backoff: the delay after failed attempt n (1-based) is
 * {@code min(maxDelayMs, baseDelayMs * 2^(n-1))}. A job dies once {@code maxAttempts} attempts failed.
 */
public record RetryPolicy(int maxAttempts, long baseDelayMs, long maxDelayMs) {
    public RetryPolicy {
        if (maxAttempts < 1) {
            throw new IllegalArgumentException("maxAttempts must be >= 1");
        }
        if (baseDelayMs < 1) {
            throw new IllegalArgumentException("baseDelayMs must be >= 1 so a retry is never due immediately");
        }
        if (maxDelayMs < baseDelayMs) {
            throw new IllegalArgumentException("maxDelayMs must be >= baseDelayMs");
        }
    }

    /** Delay before the next attempt after {@code failedAttempt} attempts have failed. */
    public long delayAfter(int failedAttempt) {
        if (failedAttempt < 1) {
            throw new IllegalArgumentException("failedAttempt must be >= 1");
        }
        int shift = failedAttempt - 1;
        if (shift >= 62 || baseDelayMs > (maxDelayMs >> shift)) {
            return maxDelayMs;
        }
        return baseDelayMs << shift;
    }
}

package ae.jobs.journal;

import java.util.List;

/** Append-only line log. {@code append} must be durable when it returns. */
public interface Journal {
    /** Appends one line (no newline characters). */
    void append(String line);

    /** Returns every complete line in append order. */
    List<String> readAll();
}

package ae.jobs.journal;

import java.io.IOException;
import java.io.UncheckedIOException;
import java.nio.ByteBuffer;
import java.nio.channels.FileChannel;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardOpenOption;
import java.util.ArrayList;
import java.util.List;
import java.util.Objects;

/**
 * File-backed journal. Each append writes {@code line + '\n'} and forces it to disk. Opening trims a torn
 * tail (bytes after the last newline, left by a crash mid-write) so later appends start on a clean line.
 */
public final class FileJournal implements Journal {
    private final Path path;

    public FileJournal(Path path) {
        this.path = Objects.requireNonNull(path, "path");
        try {
            if (Files.exists(path)) {
                trimTornTail();
            }
        } catch (IOException ex) {
            throw new UncheckedIOException(ex);
        }
    }

    private void trimTornTail() throws IOException {
        byte[] data = Files.readAllBytes(path);
        int keep = data.length;
        while (keep > 0 && data[keep - 1] != '\n') {
            keep--;
        }
        if (keep != data.length) {
            try (FileChannel ch = FileChannel.open(path, StandardOpenOption.WRITE)) {
                ch.truncate(keep);
                ch.force(true);
            }
        }
    }

    @Override
    public synchronized void append(String line) {
        Objects.requireNonNull(line, "line");
        if (line.indexOf('\n') >= 0 || line.indexOf('\r') >= 0) {
            throw new IllegalArgumentException("line must not contain newlines");
        }
        ByteBuffer buf = ByteBuffer.wrap((line + "\n").getBytes(StandardCharsets.UTF_8));
        try (FileChannel ch = FileChannel.open(path, StandardOpenOption.CREATE, StandardOpenOption.WRITE,
                StandardOpenOption.APPEND)) {
            while (buf.hasRemaining()) {
                ch.write(buf);
            }
            ch.force(false);
        } catch (IOException ex) {
            throw new UncheckedIOException(ex);
        }
    }

    @Override
    public synchronized List<String> readAll() {
        if (!Files.exists(path)) {
            return List.of();
        }
        try {
            String text = new String(Files.readAllBytes(path), StandardCharsets.UTF_8);
            List<String> out = new ArrayList<>();
            int start = 0;
            int nl;
            while ((nl = text.indexOf('\n', start)) >= 0) {
                out.add(text.substring(start, nl));
                start = nl + 1;
            }
            // Anything after the last newline is a torn write and is ignored.
            return out;
        } catch (IOException ex) {
            throw new UncheckedIOException(ex);
        }
    }
}

package ae.jobs.journal;

import java.util.ArrayList;
import java.util.List;
import java.util.Objects;

/** Journal kept in memory; used by tests and as the simplest adapter. */
public final class InMemoryJournal implements Journal {
    private final List<String> lines = new ArrayList<>();

    @Override
    public synchronized void append(String line) {
        Objects.requireNonNull(line, "line");
        if (line.indexOf('\n') >= 0 || line.indexOf('\r') >= 0) {
            throw new IllegalArgumentException("line must not contain newlines");
        }
        lines.add(line);
    }

    @Override
    public synchronized List<String> readAll() {
        return List.copyOf(lines);
    }
}

